import{_ as a,C as t,c as i,o as l,aa as r,G as o}from"./chunks/framework.Cn7WEiMX.js";const b=JSON.parse('{"title":"StairBlockRenderer","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/developers/classes/stairblockrenderer-class.md","filePath":"wiki/Dynmap/developers/classes/stairblockrenderer-class.md"}'),n={name:"wiki/Dynmap/developers/classes/stairblockrenderer-class.md"};function s(p,e,u,x,h,_){const c=t("NolebaseGitContributors"),d=t("NolebaseGitChangelog");return l(),i("div",null,[e[0]||(e[0]=r('<h1 id="stairblockrenderer" tabindex="-1">StairBlockRenderer <a class="header-anchor" href="#stairblockrenderer" aria-label="Permalink to &quot;StairBlockRenderer&quot;">​</a></h1> <p>StairBlockRender 类定义了渲染标准楼梯方块的着色器。使用时，需要用它处理所有给定楼梯方块的元数据值。着色器还会处理所有楼梯方块的连接样式及朝向（倒置等）。</p> <p>着色器可以在如下两个方法中选择一个，为楼梯选择使用的纹理：</p> <ul><li>正常（非 TileEntity 方块），由补丁提供纹理（一个用于侧面，一个用于顶面，一个用于底面）</li> <li>对于基于 TileEntity 的方块，读取 TileEntity 内的指定字段，并执行一次映射搜索，寻找需要用到给定方块所有面的补丁纹理。</li></ul> <h2 id="属性" tabindex="-1">属性 <a class="header-anchor" href="#属性" aria-label="Permalink to &quot;属性&quot;">​</a></h2> <ul><li><code>textureindex</code> - 可选参数，指定渲染方块的 TileEntity 属性名称，对有值（数字或字符串）的方块选择使用的纹理补丁。</li> <li><code>texturecnt</code> - 可选参数，需要与 <code>textureindex</code> 搭配使用，否则无效。指定映射补丁纹理，进一步定义 <code>textureindex</code> 的指定位置：值的格式为 <code>textmap</code>，后接数字 <code>texturecnt-1</code>。其中 <code>cnt</code> 是 <code>count</code> 的缩写。</li> <li><code>textmap&lt;N&gt;</code> - 从 <code>数字</code>=0 到 <code>数字</code>=（<code>texturecnt</code>-1），包含读取自 TileEntity 字段，按 <code>textureindex</code> 读取表示台阶对应纹理取自 <code>patch&lt;数字&gt;</code> 的值。</li></ul> <h2 id="需要纹理的补丁" tabindex="-1">需要纹理的补丁 <a class="header-anchor" href="#需要纹理的补丁" aria-label="Permalink to &quot;需要纹理的补丁&quot;">​</a></h2> <p>若 <code>textureindex</code> 未设置：</p> <ul><li><code>patch0</code> - 用于方块任意侧面（垂直面）的纹理</li> <li><code>patch1</code> - 方块顶部使用的纹理</li> <li><code>patch2</code> - 方块底部使用的纹理</li></ul> <p>若 <code>textureindex</code> 已设置：</p> <ul><li><code>patch0</code> - 当方块对应 TileEntity 下的 <code>textureindex</code> 字段等于 <code>textmap0</code> 属性的值时，为所有侧面应用的纹理。</li> <li><code>patch1</code> - 当方块对应 TileEntity 下的 <code>textureindex</code> 字段等于 <code>textmap1</code> 属性的值时，为所有侧面应用的纹理。</li> <li><code>patch&lt;数字&gt;</code> - 当方块对应 TileEntity 下的 <code>textureindex</code> 字段等于 <code>textmap&lt;数字&gt;</code> 属性的值时，为所有侧面应用的纹理。</li></ul> ',22)),o(c),o(d)])}const k=a(n,[["render",s]]);export{b as __pageData,k as default};
